begin;
create temp table assertions(label text);
grant select,insert on assertions to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;insert into assertions values(label);end$$;
insert into auth.users(id,email,is_anonymous) values('16000000-0000-4000-8000-000000000001','guide-a@qa.invalid',false),('16000000-0000-4000-8000-000000000002','guide-b@qa.invalid',false),('16000000-0000-4000-8000-000000000003',null,true),('16000000-0000-4000-8000-000000000004',null,true);
insert into public.classes(id,owner_id,label,grade,student_count,runtime_mode) values('16000000-0000-4000-8000-000000000005','16000000-0000-4000-8000-000000000001','7H',7,16,'demo');
insert into pn_private.presentation_sessions(id,class_id,owner_id) values('16000000-0000-4000-8000-000000000006','16000000-0000-4000-8000-000000000005','16000000-0000-4000-8000-000000000001');
create temp table guidance_fixture(binding jsonb,state jsonb);
insert into guidance_fixture values('{"presentationId":"16000000-0000-4000-8000-000000000007","channelEpoch":"16000000-0000-4000-8000-000000000008","taskEpoch":"16000000-0000-4000-8000-000000000009"}',
'{"schemaVersion":1,"mode":"station","question":1,"taskEpoch":"16000000-0000-4000-8000-000000000009","groups":[],"tool":{"kind":"ratio","baseX":2,"baseY":3,"targetX":6}}');
grant select on guidance_fixture to authenticated;
insert into pn_private.presentations(id,session_id,owner_id,board_id,channel_epoch,public_state) select '16000000-0000-4000-8000-000000000007','16000000-0000-4000-8000-000000000006','16000000-0000-4000-8000-000000000001','16000000-0000-4000-8000-000000000003','16000000-0000-4000-8000-000000000008',state from guidance_fixture;
select pg_temp.ok(pn_private.valid_public_state(state||'{"guidance":{"hint":2,"reveal":true}}'),'teacher practice flags accepted') from guidance_fixture;
select pg_temp.ok(not pn_private.valid_public_state(state||'{"guidance":{"hint":2,"reveal":true,"answerKey":"A"}}'),'no assessment key in guidance') from guidance_fixture;
select pg_temp.ok(not pn_private.valid_public_state(state||'{"guidance":{"hint":4,"reveal":true}}'),'hint bounded') from guidance_fixture;
select pg_temp.ok(not pn_private.valid_public_state(state||'{"mode":"check","guidance":{"hint":0,"reveal":true}}'),'check cannot reveal') from guidance_fixture;
select pg_temp.ok(not pn_private.valid_public_state(state||'{"mode":"exit","guidance":{"hint":0,"reveal":true}}'),'exit cannot reveal') from guidance_fixture;
set local role authenticated;
set local request.jwt.claims='{"sub":"16000000-0000-4000-8000-000000000004","is_anonymous":true}';
select pg_temp.ok((select public.guidance_status(binding||'{"action":"ack","hint":2}')->>'error'='FORBIDDEN' from guidance_fixture),'other board denied');
set local request.jwt.claims='{"sub":"16000000-0000-4000-8000-000000000002","is_anonymous":false}';
select pg_temp.ok((select public.guidance_status(binding||'{"action":"read"}')->>'error'='FORBIDDEN' from guidance_fixture),'other teacher denied');
set local request.jwt.claims='{"sub":"16000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.guidance_status(binding||'{"action":"ack","hint":2,"reveal":true}')->>'error'='INVALID_INPUT' from guidance_fixture),'board reveal denied');
select pg_temp.ok((select public.guidance_status(binding||'{"action":"ack","hint":2,"name":"CANARY"}')->>'error'='INVALID_INPUT' from guidance_fixture),'extra private field denied');
select pg_temp.ok((select public.guidance_status(binding||'{"action":"ack","hint":2}')->>'hint'='2' from guidance_fixture),'opened hint reported');
select pg_temp.ok((select public.guidance_status(binding||'{"action":"ack","hint":1}')->>'hint'='2' from guidance_fixture),'old hint cannot regress progress');
select pg_temp.ok((select public.guidance_status(binding||'{"action":"ack","hint":3,"taskEpoch":"16000000-0000-4000-8000-000000000010"}')->>'error'='CONFLICT' from guidance_fixture),'stale hint rejected');
set local request.jwt.claims='{"sub":"16000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select public.guidance_status(binding||'{"action":"read"}')->>'hint'='2' from guidance_fixture),'owner sees applied hint count');
select pg_temp.ok((select public.guidance_status(binding||'{"action":"ack","hint":3}')->>'error'='FORBIDDEN' from guidance_fixture),'teacher cannot impersonate board receipt');
reset role;
update pn_private.presentations set public_state=jsonb_set(public_state,'{taskEpoch}','"16000000-0000-4000-8000-000000000010"') where id='16000000-0000-4000-8000-000000000007';
set local role authenticated;
select pg_temp.ok((select public.guidance_status(binding||'{"action":"read","taskEpoch":"16000000-0000-4000-8000-000000000010"}')->>'hint'='0' from guidance_fixture),'new task starts with zero opened hints');
select 'PASS '||count(*)||' guidance SQL assertions' from assertions;
rollback;
